// Package domain contains the Core entities, value objects and rules:
// developers, projects, buildings, sections, lots, lot listings and their
// state history, project relations, portfolio membership and data sources.
//
// The package is pure Go: it knows nothing about the database, HTTP or other
// modules. See docs/architecture/core-domain-model.md and core-mvp.md.
package domain

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"time"
)

// ID is a canonical Realty Radar identifier: a UUIDv7 generated by the
// application (ADR-0003, ADR-0006). It never derives from external data.
type ID [16]byte

// ErrInvalidID is returned by ParseID for malformed input.
var ErrInvalidID = errors.New("invalid id")

// NewID returns a new time-ordered UUIDv7 (RFC 9562).
func NewID() ID {
	var id ID
	// crypto/rand.Read never returns an error on supported platforms.
	_, _ = rand.Read(id[6:])
	var ms [8]byte
	binary.BigEndian.PutUint64(ms[:], uint64(time.Now().UnixMilli()))
	copy(id[:6], ms[2:])
	id[6] = (id[6] & 0x0f) | 0x70 // version 7
	id[8] = (id[8] & 0x3f) | 0x80 // RFC 4122 variant
	return id
}

// ParseID parses the canonical textual form xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx.
func ParseID(s string) (ID, error) {
	var id ID
	if len(s) != 36 || s[8] != '-' || s[13] != '-' || s[18] != '-' || s[23] != '-' {
		return id, ErrInvalidID
	}
	hexDigits := s[0:8] + s[9:13] + s[14:18] + s[19:23] + s[24:36]
	if _, err := hex.Decode(id[:], []byte(hexDigits)); err != nil {
		return ID{}, ErrInvalidID
	}
	return id, nil
}

// String returns the canonical textual form of the ID.
func (id ID) String() string {
	var buf [36]byte
	hex.Encode(buf[0:8], id[0:4])
	buf[8] = '-'
	hex.Encode(buf[9:13], id[4:6])
	buf[13] = '-'
	hex.Encode(buf[14:18], id[6:8])
	buf[18] = '-'
	hex.Encode(buf[19:23], id[8:10])
	buf[23] = '-'
	hex.Encode(buf[24:36], id[10:16])
	return string(buf[:])
}

// IsZero reports whether the ID is unset.
func (id ID) IsZero() bool {
	return id == ID{}
}
